def status(service: str) -> dict:
    return {"service": service, "up": True}


@server.tool()
def pending() -> int:
    return 0


@server.tool(structured_output=False)
def greet(who: str) -> str:
    return f"hi {who}"


@server.tool()
def deploy(version: str) -> str:
    raise ValueError("no such version")


def call(name, arguments):
    async def go():
        async with Client(server) as client:
            return await run_tool(client.session, name, arguments)

    return anyio.run(go)


def test_returns_structured_output():
    assert call("status", {"service": "api"}) == {"service": "api", "up": True}


def test_returns_falsy_structured_output():
    assert call("pending", {}) == 0


def test_returns_text_without_structured_output():
    assert call("greet", {"who": "ops"}) == "hi ops"


def test_raises_when_tool_fails():
    with pytest.raises(ToolCallFailed) as info:
        call("deploy", {"version": "9.9.9"})
    assert info.value.tool == "deploy"
    assert "no such version" in info.value.message

